/* ---------- Lote 2: ítems nuevos de las habilidades de entrada ---------- */
Object.assign(LANG.es.items,{
v6:{title:"La cuenta del mostrador",prompt:"Dos panes a 4 reales y una cuenta hecha de memoria. ¿Qué imprime el programa?",hint:"En programación, igual que en matemática, la multiplicación se resuelve antes que la suma.",why:"Primero 3 × 4 = 12, después 2 + 12 = 14. Para sumar antes habría que escribir (2 + 3) * 4.",analogy:"Es la fila preferencial de la caja: quien tiene prioridad pasa primero, aunque haya llegado después. Los paréntesis son el pase que cambia el orden."},
v7:{title:"Los centavos que desaparecen",prompt:"Doña Lúcia suma dos importes y los compara con lo esperado. ¿Qué imprime el programa?",hint:"Los números decimales se guardan en binario, y no todo decimal cabe exactamente en esa forma.",why:"En binario, 0,1 y 0,2 son periódicos: la suma da 0,30000000000000004 y la comparación exacta falla. Para dinero se compara con una tolerancia o se trabaja en centavos, con números enteros.",analogy:"Es como medir con una regla en pulgadas un corte en centímetros: cada conversión deja un resto invisible, y sumar restos termina corriendo el total."},
v8:{title:"Los gramos se volvieron toneladas",prompt:"La receta usa 500 gramos de harina, pero el programa imprime 500000. ¿Qué línea está mal?",hint:"Un kilo tiene mil gramos. Para pasar de gramos a kilos, ¿se multiplica o se divide?",why:"La conversión está invertida: de gramos a kilos se divide por 1000. Multiplicar va en la dirección opuesta.",analogy:"Es cambiar moneda en el sentido equivocado: el número queda enorme y la cuenta parece bien hasta que alguien mira el total."},
v9:{title:"Cambiar los frascos sin perder el contenido",prompt:"Arma el programa que intercambia los valores de a y b usando una variable temporal e imprime el resultado.",hint:"Guarda uno de los valores antes de sobrescribirlo.",why:"La variable temporal sostiene el primer valor mientras se lo reemplaza. Sin ella se pierde uno de los dos, como en el ticket de la caja donde el intercambio fallaba.",analogy:"Para intercambiar el contenido de dos vasos llenos usas un tercer vaso vacío. Es el mismo movimiento, en código."},
v10:{title:"Entero o decimal",prompt:"Clasifica cada dato de la panadería según el tipo numérico más adecuado.",bins:["Número entero","Número decimal"],cards:["Cantidad de panes vendidos en el día","Precio del kilo de harina","Cantidad de clientes en la fila","Peso de la masa en kilos"],hint:"Pregúntate si tiene sentido que exista la mitad de eso.",why:"Lo que se cuenta de a una unidad pide entero; lo que se mide en partes pide decimal. Medio cliente no existe; medio kilo, sí.",analogy:"Es la diferencia entre contar huevos y pesar harina: uno entra en la caja, el otro pide balanza."},
c6:{title:"Una pregunta dentro de otra",prompt:"¿Qué imprime el programa?",hint:"La segunda prueba solo ocurre si la primera es verdadera.",why:"5 > 3 es verdadero, así que entra al bloque interno. Ahí, 5 > 10 es falso y el programa cae en el else interno. El else externo nunca se alcanza.",analogy:"Es el triaje con dos puertas: quien pasa la primera todavía encuentra otra decisión más adelante, y quien no pasa ni llega a verla."},
c7:{title:"Un adulto mayor sin prioridad",prompt:"Los pacientes de 65 años o más, y también los niños de hasta 12, deberían tener prioridad. El programa nunca marca a nadie. ¿Qué línea hay que corregir?",hint:"¿Existe alguna edad que sea al mismo tiempo mayor que 65 y menor que 12?",why:"Con Y, las dos condiciones tienen que cumplirse juntas, lo cual es imposible. La regla une dos grupos distintos, así que pide O.",analogy:"Es el cartel \"entrada para adultos mayores y niños\": nadie es las dos cosas a la vez. Cambiar el \"y\" por el \"o\" abre la puerta a los dos grupos."},
c8:{title:"El límite entra o queda afuera",prompt:"Clasifica cada condición del triaje según qué hace con el valor exacto del límite.",bins:["Incluye el límite","Excluye el límite"],cards:["temperatura >= 39","temperatura > 39","edad <= 12","edad < 12"],hint:"La rayita debajo del signo es la que carga el \"o igual\".",why:"Los signos >= y <= incluyen el valor del límite; > y < dejan justamente ese valor afuera. Ahí nacen los errores de frontera.",analogy:"Es la diferencia entre \"a partir de los 65\" y \"más de 65\": quien tiene exactamente 65 entra en un caso y queda afuera en el otro."},
c9:{title:"El triaje de Rosa, en tres niveles",prompt:"Arma el triaje: fiebre de 39 o más es rojo; si no, edad de 65 o más es amarillo; los demás, verde.",hint:"La regla más grave va primero, y cada paciente sale con un único nivel.",why:"La cadena if, elif y else garantiza que se asigne un solo nivel y que la regla más grave se pruebe antes. Los datos tienen que existir antes de la prueba, y la impresión va después de la decisión.",analogy:"Es el protocolo colgado en la pared del centro de salud: se lee de arriba abajo y uno se detiene en la primera línea que aplica."},
c10:{title:"La división que no ocurre",prompt:"Con x igual a cero, dividir por x daría error. ¿Qué imprime el programa?",hint:"Cuando la primera prueba de un Y ya es falsa, ¿la segunda llega a evaluarse?",why:"El operador Y evalúa en cortocircuito: como x != 0 es falso, la división nunca se ejecuta y el programa sigue al else, sin error. Ese patrón protege operaciones riesgosas.",analogy:"Es fijarse si hay nafta antes de arrancar: si no hay, nadie gira la llave. El orden de las pruebas es la protección."},
q7:{title:"Descubrir o comprobar",prompt:"Clasifica cada actividad de la ingeniería de requisitos.",bins:["Elicitación (descubrir)","Validación (comprobar)"],cards:["Entrevistar a la recepcionista sobre el día a día de la atención","Revisar la lista de requisitos con la directora antes de programar","Observar a los pacientes usando el tótem de turnos","Mostrar un prototipo y verificar si es eso lo que se espera"],hint:"Pregúntate si la actividad busca información nueva o confirma lo que ya se escribió.",why:"Entrevistar y observar sacan a la luz requisitos que todavía no estaban en papel. Revisar y comprobar prototipos verifican si lo escrito corresponde a la necesidad real.",analogy:"Es la diferencia entre tomarle las medidas al cliente y probarle la ropa. La primera descubre; la segunda confirma."},
q8:{title:"El camino de un requisito",prompt:"Ordena las etapas de la ingeniería de requisitos.",lines:["Elicitación: descubrir qué necesitan las personas","Análisis: resolver conflictos y definir prioridades","Especificación: escribir los requisitos de forma verificable","Validación: comprobar con quien lo pidió si es eso","Gestión: controlar los cambios a lo largo del proyecto"],hint:"Primero se descubre, después se organiza, se escribe y se comprueba; controlar los cambios acompaña todo lo demás.",why:"Cada etapa alimenta a la siguiente: no se prioriza lo que no se relevó, ni se valida lo que no se escribió. La gestión entra cuando los requisitos empiezan a cambiar, y siempre cambian.",analogy:"Es construir una casa: conversar con la familia, decidir qué entra en el presupuesto, dibujar el plano, mostrar el dibujo y después registrar cada cambio de idea."},
q9:{title:"\"El sistema avisa al paciente\"",prompt:"El requisito dice solamente: \"el sistema avisa al paciente\". ¿Por qué es problemático?",opts:["No dice cuándo, por qué medio ni qué hacer si el aviso falla","Es demasiado largo y habría que dividirlo","Usa la palabra sistema, que habría que evitar","No tiene problema: está bastante claro"],hint:"Imagina a dos personas implementando esa frase sin hablar entre sí. ¿Saldría lo mismo?",why:"Un requisito ambiguo es el que admite más de una lectura razonable. Avisar la víspera por mensaje es distinto de avisar en el momento por correo, y las dos caben en esa frase.",analogy:"Es decirle a un amigo \"avísame\": puede llamar a las seis de la mañana o dejar el recado con el vecino. Sin acordarlo, cada uno cumple a su manera."},
q10:{title:"Criterios de aceptación",prompt:"¿Qué convierte una historia de usuario en algo que el equipo sabe cuándo terminó?",opts:["Criterios de aceptación: condiciones verificables que dicen cuándo está lista","La estimación en horas del desarrollador","El nombre de quien pidió la funcionalidad","La pantalla dibujada por el diseñador"],hint:"Piensa en lo que permite responder sí o no a: ¿ya terminó?",why:"Los criterios de aceptación describen, en condiciones verificables, el comportamiento esperado. Sin ellos, \"listo\" se vuelve opinión.",analogy:"Es la lista de la inspección al recibir un departamento: sin ella, entregar las llaves termina en discusión sobre lo acordado."},
q11:{title:"Dos pedidos que se contradicen",prompt:"La directora quiere un registro completo del paciente; la recepción quiere agendar en menos de un minuto. ¿Cuál es la mejor conducta?",opts:["Llevar el conflicto a ambas partes y negociar una solución explícita, como registro mínimo ahora y completo después","Hacerle caso a la directora, porque tiene más autoridad","Hacerle caso a la recepción, porque está más cerca del problema","Implementar las dos cosas y que lo resuelvan en el uso"],hint:"Un conflicto entre requisitos es un problema que se resuelve en el análisis, no en el código.",why:"Los requisitos en conflicto tienen que reconciliarse con las partes interesadas antes de volverse código. Elegir en silencio traslada el conflicto al producto, donde cuesta mucho más caro.",analogy:"Son dos ambientes que se disputan la misma pared en el plano. El arquitecto se sienta con la familia y decide antes; una vez levantada, la pared cuesta una obra."},
g7:{title:"Deshacer sin borrar la historia",prompt:"Un cambio ya publicado rompió el sistema de la panadería. Ordena los pasos para deshacerlo con seguridad.",lines:["Identificar en el historial el commit que causó la falla","Crear un commit de reversión que deshaga esos cambios","Correr las pruebas para confirmar que el sistema volvió a la normalidad","Publicar la reversión en el repositorio remoto","Investigar la causa con calma y preparar la corrección definitiva"],hint:"Primero restablece el servicio; entender el porqué viene después, con el sistema estable.",why:"La reversión crea un commit nuevo que deshace el anterior, sin borrar el historial que otras personas ya descargaron. Investigar después es seguro porque el sistema ya volvió a funcionar.",analogy:"En contabilidad no se tacha un asiento equivocado: se hace un asiento de reversión. El error queda registrado y la cuenta vuelve a estar bien."},
g8:{title:"Traer o ya mezclar",prompt:"¿Cuál es la diferencia entre fetch y pull en Git?",opts:["Fetch solo trae los cambios del remoto; pull los trae y ya los integra en tu rama","Son dos nombres para la misma operación","Fetch envía cambios; pull los recibe","Fetch funciona solo en main; pull en cualquier rama"],hint:"Una de las dos cambia tus archivos en el momento. ¿Cuál?",why:"Fetch actualiza tu vista del repositorio remoto sin tocar tu trabajo, y te deja ver qué cambió antes de integrar. Pull hace las dos cosas de una vez y puede generar un conflicto ahí mismo.",analogy:"Es la diferencia entre retirar la correspondencia y abrir los sobres sobre el escritorio donde estás trabajando. Fetch la deja en el buzón; pull la desparrama ahora."},
g9:{title:"Qué entra al repositorio",prompt:"Clasifica cada archivo del proyecto de la panadería.",bins:["Versionar","Dejar afuera (.gitignore)"],cards:["El código fuente del cálculo del vuelto","El archivo con la contraseña de la base de datos","El README con instrucciones de instalación","La carpeta de bibliotecas descargadas automáticamente"],hint:"Pregúntate si el archivo lo escribió el equipo y si puede verlo cualquiera con acceso al repositorio.",why:"Se versiona lo que el equipo escribe y necesita compartir. Los secretos nunca entran, porque el historial de Git es permanente; las dependencias descargadas tampoco, porque se reconstruyen desde el archivo de dependencias.",analogy:"Es armar la valija: tu ropa va, el champú del hotel se queda. Y la llave de casa no viaja en una valija abierta de ninguna manera."},
g10:{title:"La publicación forzada",prompt:"Un colega propone usar publicación forzada en la rama principal para \"limpiar\" el historial. ¿Por qué es peligroso?",opts:["Reescribe el historial que los demás ya descargaron y puede borrar su trabajo","Deja el repositorio más lento","Solo funciona con permisos de administrador","No es peligroso: es la forma recomendada de ordenar los commits"],hint:"¿Qué pasa con quien ya descargó la versión anterior y siguió trabajando sobre ella?",why:"La publicación forzada reemplaza el historial del remoto. Los commits que otras personas ya descargaron desaparecen de la línea de tiempo, y el trabajo hecho sobre ellos queda huérfano. En una rama compartida se prefiere revertir.",analogy:"Es reimprimir el acta de una reunión que todos ya se llevaron a casa. Quien anotó sobre la versión vieja se queda con un documento que ya no existe."},
g11:{title:"El commit que hace de todo",prompt:"Un commit cambia el cálculo del vuelto, renombra veinte variables y agrega una pantalla nueva. ¿Cuál es el problema?",opts:["No se puede revisar, revertir ni rastrear el origen de un defecto por separado","Ninguno: los commits grandes ahorran tiempo","Git tiene un límite de archivos por commit","El mensaje va a quedar demasiado largo"],hint:"Piensa en el día en que haya que deshacer solo uno de esos tres cambios.",why:"Cada commit debería contener un cambio coherente. Al mezclar tres, la reversión se lleva lo que estaba bien, y la revisión se pierde entre renombres y lógica nueva.",analogy:"Es embalar la cocina, el baño y el escritorio en la misma caja. Para encontrar una taza das vuelta todo, y no puedes devolver solo lo que vino mal."}
});
